import assert from 'node:assert/strict';
import {mkdir,writeFile} from 'node:fs/promises';
import {chromium} from 'playwright';

const WEB_BASE=(process.env.CHECK_WEB_URL||'http://localhost:5173').replace(/\/$/,'');

// All API requests use browser-local fixtures; no business records are written.
const browser=await chromium.launch({channel:'msedge',headless:true});
const context=await browser.newContext({viewport:{width:1280,height:900}});
const page=await context.newPage();
const errors=[],checks=[];
page.on('pageerror',error=>errors.push(error.message));
const accounts={
  admin:{id:'mock-admin',username:'admin',name:'同步测试管理员',role:'ADMIN',orgId:'mock-org'},
  tianbo:{id:'mock-inspector',username:'tianbo',name:'同步测试检查员',role:'INSPECTOR',orgId:'mock-org'},
  zhangsan:{id:'mock-reviewer',username:'zhangsan',name:'同步测试审核员',role:'REVIEWER',orgId:'mock-org'},
  lisi:{id:'mock-rechecker',username:'lisi',name:'同步测试复查员',role:'RECHECKER',orgId:'mock-org'}
};
let account=accounts.admin,stateRequests=0,failState=false,expireState=false,blockState=false,releaseState;
let activeState=0,maxActiveState=0;
let extraChecklists={};
let issues=[],events=[],extraTasks=[],conflictSite=false,conflictIssue=false,conflictFinish=false,mockWrites=0,lastReview=null,lastTaskPayload=null,failSite=false;
const otherUnit={id:'mock-other-unit',name:'另一监管单位',type:'住宅小区',address:'另一地址',people:'10人',buildings:'一栋',risk:'中风险关注',active:true};
const unit={id:'mock-unit',name:'自动同步测试单位',type:'学校',address:'测试地址',people:'20人',buildings:'一栋',risk:'低风险',active:true,updatedAt:'2026-10-13T10:00:00+08:00'};
const task={id:'mock-task',unitId:unit.id,orgId:'mock-org',source:'日常抽查',risk:'低风险',due:'2030-10-20T12:00:00+08:00',status:'进行中',version:1,progress:0,focus:['现场核验'],createdAt:'2026-10-13T10:00:00+08:00',site:{type:'学校',height:12,floors:3,people:20},inspectorId:accounts.tianbo.id,reviewerId:accounts.zhangsan.id,recheckerId:accounts.lisi.id};
const checklist=[{id:'mock-item',taskId:task.id,title:'检查项目',tip:'检查要求',group:'现场检查',status:null,note:''}];
let historyFixture={reviews:[{actorName:'审核员',createdAt:task.createdAt,opinion:'已核对',issueId:'issue-private-random-id'}],rectifications:[],rechecks:[],logs:[]},historyFileReads=0;
let accountFixture=null,lastAccountPayload=null;
let unitDetailFixture=null;
let previewPhotoBytes=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a7YQAAAAASUVORK5CYII=','base64'),releasePreview,previewFinished=false;
function visible(){return account.role==='ADMIN'||account.role==='INSPECTOR'||(account.role==='REVIEWER'&&['待审核','整改中','已完成'].includes(task.status))||(account.role==='RECHECKER'&&['整改中','已完成'].includes(task.status));}
function state(){return {user:account,tasks:visible()?[task,...extraTasks]:[],units:[unit,otherUnit],checklists:visible()?{[task.id]:checklist,...extraChecklists}:{},issues,events};}
function detail(){return {...task,unit,checklist,issues,events,history:historyFixture};}
function dashboard(){const actionable=visible()&&(account.role==='ADMIN'||(account.role==='INSPECTOR'&&['待检查','进行中'].includes(task.status))||(account.role==='REVIEWER'&&task.status==='待审核')||(account.role==='RECHECKER'&&task.status==='整改中'));return {pending:task.status==='待检查'?1:0,inProgress:task.status==='进行中'?1:0,review:visible()&&task.status==='待审核'?1:0,rectifying:visible()&&task.status==='整改中'?1:0,completed:visible()&&task.status==='已完成'?1:0,reviewed:['整改中','已完成'].includes(task.status)?1:0,highRisk:0,priorityTasks:actionable?[task]:[],unfinishedTotal:actionable?1:0};}
await page.route('**/api/**',async route=>{
  const request=route.request(),path=new URL(request.url()).pathname.slice(4);
  const respond=(data,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify({code:status===200?0:status,message:status===200?'成功':'测试失败',data})});
  if(path==='/auth/login'){account=accounts[request.postDataJSON().username];return respond({user:account,token:'mock-token-'+account.id});}
  if(path==='/auth/me')return respond(account);
  if(path==='/auth/logout')return respond({});
  if(path.startsWith('/users/')&&request.method()==='PATCH'){mockWrites++;lastAccountPayload=request.postDataJSON();const user=accountFixture.find(user=>user.id===path.slice('/users/'.length));assert.ok(user);Object.assign(user,lastAccountPayload);return respond(user);}
  if(path==='/files/photos/history-photo'){historyFileReads++;return route.fulfill({contentType:'image/png',body:previewPhotoBytes});}
  if(path==='/files/photos/preview-pdf')return route.fulfill({contentType:'application/pdf',body:'%PDF-1.4\n1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj\n2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj\n3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 300 200] >> endobj\ntrailer << /Root 1 0 R >>\n%%EOF'});
  if(path==='/files/photos/preview-error')return route.fulfill({status:404,contentType:'application/json',body:JSON.stringify({code:404,message:'附件不存在',data:{}})});
  if(path==='/files/photos/preview-slow'){await new Promise(resolve=>{releasePreview=resolve;});await route.fulfill({contentType:'image/png',body:previewPhotoBytes});previewFinished=true;return;}
  if(path==='/tasks/'+task.id+'/site-check'&&request.method()==='PUT'){
    mockWrites++;const body=request.postDataJSON();if(failSite){failSite=false;return route.fulfill({status:500,contentType:'application/json',body:JSON.stringify({code:500,message:'暂时无法保存场所条件',data:{}})});}if(conflictSite){conflictSite=false;task.version++;return route.fulfill({status:409,contentType:'application/json',body:JSON.stringify({code:409,message:'任务已被更新，请核对最新内容后重试',data:{}})});}assert.equal(body.version,task.version);task.site={...body};task.version++;return respond(task);
  }
  if(path==='/tasks/'+task.id+'/submit-review'&&request.method()==='POST'){mockWrites++;assert.equal(request.postDataJSON().version,task.version);if(checklist.some(item=>!item.status||item.status==='pending'))return route.fulfill({status:400,contentType:'application/json',body:JSON.stringify({code:400,message:'请完成全部项目核验后提交',data:{}})});task.status='待审核';task.version++;return respond(task);}
  if((path==='/tasks'&&request.method()==='POST')||(path==='/tasks/'+task.id&&request.method()==='PATCH')){mockWrites++;lastTaskPayload=request.postDataJSON();assert.equal('focus' in lastTaskPayload,false);return respond(task);}
  if(path==='/issues/issue-private-random-id'&&request.method()==='PATCH'){mockWrites++;const body=request.postDataJSON();if(conflictIssue){conflictIssue=false;task.version++;return route.fulfill({status:409,contentType:'application/json',body:JSON.stringify({code:409,message:'任务已被更新，请核对最新内容后重试',data:{}})});}assert.equal(body.version,task.version);assert.equal(body.finding,'待保留的问题事实草稿');issues[0].finding=body.finding;task.version++;return respond(issues[0]);}
  if(path==='/issues/issue-private-random-id/review'&&request.method()==='POST'){mockWrites++;lastReview=request.postDataJSON();if(lastReview.decision==='confirm'){for(const key of ['requirements','responsibleContact','rectificationDue'])assert.ok(lastReview[key]);issues[0].status='整改中';}else{for(const key of ['requirements','responsibleContact','rectificationDue'])assert.equal(key in lastReview,false);issues[0].status='已排除';}task.version++;return respond(task);}
  if(path==='/tasks/'+task.id+'/review'&&request.method()==='POST'){mockWrites++;const body=request.postDataJSON();if(body.issueReviews?.length){lastReview=body.issueReviews[0];if(lastReview.decision==='confirm'){for(const key of ['requirements','responsibleContact','rectificationDue'])assert.ok(lastReview[key]);issues[0].status='整改中';}else{for(const key of ['requirements','responsibleContact','rectificationDue'])assert.equal(key in lastReview,false);issues[0].status='已排除';}task.version++;}if(conflictFinish){conflictFinish=false;task.status='整改中';task.version++;return route.fulfill({status:409,contentType:'application/json',body:JSON.stringify({code:409,message:'任务阶段已改变，请查看最新任务',data:{}})});}return respond(task);}
  assert.equal(request.method(),'GET','所有业务写入必须被浏览器模拟截获');
  if(path==='/checklist-options'){const second=new URL(request.url()).searchParams.get('unitId')===otherUnit.id;return respond([{id:'option-a',title:'消防设施检查',tip:'核对设备状态'},{id:second?'option-c':'option-b',title:second?'住宅疏散检查':'学校疏散检查',tip:'检查通道'}]);}

  if(path==='/state'){
    stateRequests++;activeState++;maxActiveState=Math.max(maxActiveState,activeState);
    try{
      if(blockState){blockState=false;await new Promise(resolve=>{releaseState=resolve;});}
      if(expireState)return respond({},401);
      if(failState)return respond({},503);
      return respond(state());
    }finally{activeState--;}
  }
  if(path==='/dashboard')return respond(dashboard());
  if(path==='/users')return respond(accountFixture||Object.values(accounts).map(user=>({...user,enabled:true})));
  if(path==='/tasks/'+task.id)return respond(detail());
  if(path==='/units/'+unit.id)return respond({...unit,...(unitDetailFixture||{tasks:visible()?[task]:[],issues,events})});
  throw new Error('未预期接口：'+path);
});

async function login(username){await page.locator('[name="username"]').fill(username);await page.locator('[name="password"]').fill('fixture-password');await page.getByRole('button',{name:'登录',exact:true}).click();await page.getByRole('heading',{name:'你好，'+accounts[username].name,exact:true}).waitFor();}
async function logout(){await page.locator('.sidebar [data-view="profile"]').click();await page.getByRole('button',{name:'退出登录',exact:true}).click();await page.getByRole('heading',{name:'登录工作台',exact:true}).waitFor();}
async function advance(milliseconds=5000){await page.clock.runFor(milliseconds);}
async function waitUntil(predicate){for(let attempt=0;attempt<200;attempt++){if(predicate())return;await new Promise(resolve=>setTimeout(resolve,10));}assert.fail('等待浏览器请求处理超时');}
async function settle(){await page.waitForFunction(()=>document.querySelector('#app')?.dataset.syncAt===new Date().toISOString());}
async function expectSync(){const previous=await page.locator('#app').getAttribute('data-sync-at');await advance();await page.waitForFunction(value=>{const stamp=document.querySelector('#app')?.dataset.syncAt;return !!stamp&&stamp!==value;},previous);}
async function remember(selector){await page.evaluate(selector=>{window.testRoot=document.querySelector('#app');window.testNode=document.querySelector(selector);window.testNavigation=performance.getEntriesByType('navigation').length;},selector);}
async function expectSame(selector){assert.deepEqual(await page.evaluate(selector=>({root:document.querySelector('#app')===window.testRoot,node:document.querySelector(selector)===window.testNode,navigation:performance.getEntriesByType('navigation').length===window.testNavigation}),selector),{root:true,node:true,navigation:true});}

page.setDefaultTimeout(10000);
async function navView(view){await page.locator(`.sidebar [data-view="${view}"]`).click();}
