async function closeDialog(){await page.getByRole('button',{name:'取消',exact:true}).click();}
async function phaseView(phase){await page.locator(`.flow-step[data-phase="${phase}"]`).click();}
async function saveDialog(){await page.locator('[role="dialog"] button[type="submit"]').click();await page.locator('[role="dialog"]').waitFor({state:'hidden'});}
async function cleanCopy(){const text=await page.locator('#app').innerText();for(const word of ['每5秒自动同步','最近同步','立即同步','服务端','下发后独立保存','档案保留原始','确认时必填','仍须审核清单','只有分配的审核人员','最近更新优先','生成独立风险事项'])assert.equal(text.includes(word),false,word);}
